def finalize_external_transfer(receipt_id, receipt):
    with db.transaction():
        lock_transfer_and_accounts('T7')
        if terminal_receipt_already_applied(receipt_id): return stored_result()
        require(receipt_is_final_and_matches_operation('T7'))
        require(state in {'SUBMITTED', 'UNKNOWN', 'RECONCILING'})
        if receipt.confirms_execution:
            append_balanced_postings([('A', -15000), ('clearing', 15000)])
            consume_reservation_once('T7')
            set_state('SETTLED')
        elif receipt.confirms_non_execution:
            release_reservation_once('T7'); set_state('REJECTED_FINAL')
        persist_receipt_and_outbox()

def read_conditions(req, deadline):
    view = projection.read_coherent(req.account)
    if satisfies(view, req.contract):
        return ready(view)
    result = wait_for_progress_bounded(req, deadline)
    if satisfies(result, req.contract):
        return ready(result)
    with fallback.try_admit(deadline) as permit:
        if not permit:
            return pending_or_unavailable(req.contract)
        result = canonical.read_at_least(req.token, deadline)
        return ready(result) if satisfies(result, req.contract) else pending()

